fn is_sorted(a: &[i32]) -> bool {
    // An array of length 0 or 1 is trivially sorted
    if a.len() < 2 {
        return true;
    }

    // Check every adjacent pair
    for i in 1..a.len() {
        if a[i] < a[i - 1] {
            return false;
        }
    }

    true
}